/// - `branch`: [branch](https://git-scm.com/docs/gitglossary#Documentation/gitglossary.txt-aiddefbranchabranch)
/// - `tag`: [tag](https://git-scm.com/docs/gitglossary#Documentation/gitglossary.txt-aiddeftagatag)
///
/// Stability: release_candidate.
#[cfg(feature = "experimental")]
pub const VCS_REF_TYPE: &str = "vcs.ref.type";

/// The human readable name of the repository. It SHOULD NOT include any additional identifier
/// like Group/SubGroup in GitLab or organization in GitHub.
///
/// Due to it only being the name, it can clash with forks of the same
/// repository if collecting telemetry across multiple orgs or groups in
/// the same backends.
///
/// Stability: release_candidate.
#[cfg(feature = "experimental")]
pub const VCS_REPOSITORY_NAME: &str = "vcs.repository.name";

/// The [canonical URL](https://support.google.com/webmasters/answer/10347851) of the repository
/// providing the complete HTTP(S) address in order to locate and identify the repository through
/// a browser.
///
/// In Git Version Control Systems, the canonical URL SHOULD NOT include
/// the `.git` extension.
///
/// Stability: release_candidate.
#[cfg(feature = "experimental")]
pub const VCS_REPOSITORY_URL_FULL: &str = "vcs.repository.url.full";

/// The type of revision comparison.
///
/// Well-known values:
/// - `behind`: How many revisions the change is behind the target ref.
/// - `ahead`: How many revisions the change is ahead of the target ref.
///
/// Stability: release_candidate.
#[cfg(feature = "experimental")]
pub const VCS_REVISION_DELTA_DIRECTION: &str = "vcs.revision_delta.direction";

/// Additional description of the web engine (e.g. detailed version and edition information).
///
/// Stability: development.
#[cfg(feature = "experimental")]
pub const WEBENGINE_DESCRIPTION: &str = "webengine.description";

/// The name of the web engine.
///
/// Stability: development.
#[cfg(feature = "experimental")]
pub const WEBENGINE_NAME: &str = "webengine.name";

/// The version of the web engine.
///
/// Stability: development.
#[cfg(feature = "experimental")]
pub const WEBENGINE_VERSION: &str = "webengine.version";

